-- Queer Atlas: verified Germany, Netherlands and Belgium events, batch 4.
-- PIP / PARISH is held as a global event because The Hague has no current city feed.

begin;

alter table if exists public.events add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.events add column if not exists ticket_url text;
alter table if exists public.global_events add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.global_events add column if not exists ticket_url text;

with src as (
 select * from jsonb_to_recordset($qa_gnb_city_events$
[
{"name":"FEUCHT Vol. 7: Mohajer & source:link","aliases":["FEUCHT with Mohajer & source:link"],"city":"berlin","date":"2026-10-23","start_date":"2026-10-23","end_date":"2026-10-24","description":"FEUCHT goes wet, late and joyfully unhinged at LARK: Mohajer and source:link lead a queer night for homosexuals, non-binary genderqueers, dykes, dads, femmes and the people who dance closest to their desires.","link":"https://ra.co/events/2409148","ticket_url":"https://ra.co/events/2409148","location":"LARK, Holzmarktstraße 15–18, 10179 Berlin, Germany","lat":52.5102,"lng":13.4307,"vibe":"late queer house ritual with sexually liberated, sweat-heavy Berlin energy","intel":{"hours":"23:59 Friday 23 October–08:00 Saturday 24 October 2026.","entry_wait":"RA and door tickets are offered, but advance purchase does not guarantee entry: the promoter uses door selection to protect the room.","best_arrival":"Come before midnight for the calmest entry and the full descent rather than gambling on the 03:00 crush.","crowd_mix":"Queers, FLINTA guests, friends and allies are welcomed; this is explicitly a queer-led space, not a generic club booking.","dress_code":"Wear less is the invitation; no mandatory costume is published, but dance-ready liberation beats polished nightlife uniform.","host_inclusivity":"The door selection is stated as a safe-space tool and tickets are refunded when a guest is declined.","lineup":"CHRANDY, Doctora Amor, Mohajer and source:link.","age_limit":"21+.","source_urls":["https://ra.co/events/2409148"],"research_status":"ticketing_listing_and_door_policy_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"VRAUWEEN: Urban Legends","aliases":["VRAUWEEN 2 CLUBS: QUEER BAILE FUNK","VRAUWEEN Queer Baile Funk"],"city":"berlin","date":"2026-10-31","start_date":"2026-10-31","end_date":"2026-11-01","description":"VRAUWEEN gives Berlin Halloween a Brazilian queer pulse: two LARK rooms of bass, baile funk and urban legends where the standard is simple — shake hard, be kind and let the stories get strange.","link":"https://ra.co/events/2522049","ticket_url":"https://ra.co/events/2522049","location":"LARK, Holzmarktstraße 15–18, 10179 Berlin, Germany","lat":52.5102,"lng":13.4307,"vibe":"queer Brazilian baile funk Halloween with loud bass, movement and two-room release","intel":{"hours":"23:00 Saturday 31 October–06:00 Sunday 1 November 2026.","entry_wait":"Buy through the active RA route and arrive early for the Halloween rush; capacity spans two rooms but demand will concentrate late.","best_arrival":"Reach LARK near 23:00 to experience both rooms before the party locks into its peak.","crowd_mix":"Queer Brazilians and diaspora, baile-funk dancers, club kids and everyone willing to join with kindness are the intended mix.","dress_code":"Urban-legend Halloween looks suit the edition; self-expression matters more than a uniform fetish threshold.","host_inclusivity":"VRAU is run by queer people and centres Brazilian queer culture while inviting open, respectful dancers.","lineup":"TBA on the latest ticket page.","age_limit":"Confirm on ticketing.","source_urls":["https://ra.co/events/2522049"],"research_status":"ticketing_listing_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"Kinktastisch! Techno. Kink. Play","aliases":["Kinktastisch Berlin October 2026"],"city":"berlin","date":"2026-10-10","start_date":"2026-10-10","end_date":"2026-10-11","description":"Kinktastisch turns Insomnia into a consent-first techno playground: an intentional fetish dress ritual, midnight show, dungeon try-outs and a floor where care is every bit as visible as the PVC.","link":"https://ra.co/events/2422852","ticket_url":"https://ra.co/events/2422852","location":"Insomnia, Alt-Tempelhof 17–19, 12099 Berlin, Germany","lat":52.4730,"lng":13.3867,"vibe":"sex-positive fetish techno with conscious play, dungeon workshops and hard dance-floor momentum","intel":{"hours":"22:00 Saturday 10 October–06:00 Sunday 11 October 2026.","entry_wait":"Door tickets are €30 and student entry €20; get there before the midnight show, dressed for the stated door policy.","best_arrival":"Arrive at 22:00 for the first DJ, orientation and a calmer wardrobe process before the late kink programme.","crowd_mix":"A mixed LGBTQIA+ and kink-positive adult crowd; couples, groups and solo guests share an explicitly inclusive space.","dress_code":"Effort and creativity are required: fetish, latex, vinyl, lingerie, burlesque, cosplay and kinky uniforms work; plain jeans, basic tees and flip-flops do not.","host_inclusivity":"Clear, ongoing consent is required; an identifiable Unicorn Awareness Team supports guests, and phones stay in the wardrobe.","lineup":"Anne Decks, Sika Akis, Francee; midnight show and try-out corners.","age_limit":"18+.","source_urls":["https://ra.co/events/2422852"],"research_status":"ticketing_listing_house_rules_and_access_policy_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"TILLAVISION: The Final Edition","aliases":["TILLAVISION Amsterdam 2026"],"city":"amsterdam","date":"2026-10-16","start_date":"2026-10-16","end_date":"2026-10-17","description":"TILLAVISION signs off with a 1970s queer-nightlife fantasia: a panel, big-hearted dance floor and the bright, unruly reminder that nightlife has always been protest, survival and chosen community.","link":"https://ra.co/events/2537558","ticket_url":"https://ra.co/events/2537558","location":"TILLATEC, Doctor Jan van Breemenstraat 1, 1056 AB Amsterdam, Netherlands","lat":52.3740,"lng":4.8518,"vibe":"fundraising queer nightlife finale mixing dark techno lineage, panel talk and 1970s glamour","intel":{"hours":"21:00 Friday 16 October–07:00 Saturday 17 October 2026.","entry_wait":"€15 is listed; buy ahead for the final edition and be ready for the early panel before the party fully opens.","best_arrival":"Be there at 21:00 to catch the discussion that frames the night, then stay for the complete closing celebration.","crowd_mix":"Queer nightlife historians, techno dancers, performers, allies and fundraiser supporters gather around freedom and self-expression.","dress_code":"The 1970s are the theme: Bowie and Cher glamour, platforms, kaftans, punk, sequins and anything that joyfully clashes.","host_inclusivity":"All proceeds go to Foundation He + HIV, supporting queer and trans people living with or affected by HIV in Suriname.","lineup":"Jackie Ong, Jay Jay Revlon, LYLO and ZOBAYDA.","age_limit":"Confirm on ticketing.","source_urls":["https://ra.co/events/2537558"],"research_status":"ticketing_listing_and_fundraiser_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"QUEER MOUSSEM FESTIVAL by Gazelle L’Hafla","aliases":["Queer Moussem Festival Gazelle L'Hafla"],"city":"brussels","date":"2026-10-30","start_date":"2026-10-30","end_date":"2026-10-31","description":"Queer Moussem is North African queerness in full motion: ancestral rhythm, ballroom, performance and acid pressure share two rooms at Les Halles, turning cultural memory into a beautiful, uncensored club reclamation.","link":"https://ra.co/events/2538609","ticket_url":"https://ra.co/events/2538609","location":"Les Halles de Schaerbeek, Rue Royale Sainte-Marie 22b, 1030 Brussels, Belgium","lat":50.8632,"lng":4.3691,"vibe":"North African queer festival of ballroom, performance, electro and acid-techno collective trance","intel":{"hours":"20:00 Friday 30 October–05:00 Saturday 31 October 2026.","entry_wait":"€15 RA tickets and an 18+ door are listed; come early for live performance before the full club peak.","best_arrival":"Arrive around 20:00 to catch the whole two-room arc: live music and performance are as central as the late floor.","crowd_mix":"Maghrebi and Levantine queer communities, ballroom dancers, diaspora artists and Brussels allies meet in a deliberately cultural rather than generic club space.","dress_code":"No mandatory code is published; bold, culturally thoughtful looks with room to dance fit the festival's ethos.","host_inclusivity":"Gazelle L’Hafla and Les Halles frame the event as a reclamation of North African queerness, bodies and collective pride.","lineup":"AramanaKhan, Redaddy b2b Eau Vive, Mamdouh313, Omar Zyami, BibilAAAA and 15+ performers including Vanity Dusk and Sherine Falasteen.","age_limit":"18+.","source_urls":["https://ra.co/events/2538609"],"research_status":"ticketing_listing_and_cultural_context_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"SIZZLEPROOF × AB Club: One Year Anniversary","aliases":["SIZZLEPROOF AB Club One Year Anniversary"],"city":"brussels","date":"2026-10-10","start_date":"2026-10-10","end_date":"2026-10-11","description":"SIZZLEPROOF celebrates a year of moving POC electronic expression to the front of the room: a sweaty AB Club takeover where afro house, techno, breaks and global club refuse tidy genre borders.","link":"https://ra.co/events/2537924","ticket_url":"https://ra.co/events/2537924","location":"AB Club, Ancienne Belgique, Anspachlaan 110, 1000 Brussels, Belgium","lat":50.8475,"lng":4.3529,"vibe":"POC-led electronic club celebration with percussive techno, afro rhythms and safer-space care","intel":{"hours":"23:00 Saturday 10 October–05:00 Sunday 11 October 2026.","entry_wait":"€12–15 ticketing is listed; book before travelling rather than relying on a late anniversary walk-up.","best_arrival":"Come for 23:00 doors to catch the live element and watch residents build the room from the start.","crowd_mix":"POC and queer guests are particularly centred, alongside respectful Brussels dancers drawn to experimental global club music.","dress_code":"No fixed code is published; expressive movement-ready clubwear makes more sense than a formal AB concert look.","host_inclusivity":"SIZZLEPROOF explicitly maintains a safer space especially for POC and queer people, with no tolerance for discrimination or harassment.","lineup":"Ezek (live), OLUWA, Gucciblck, and Hysope b2b JEKKAMAÏ.","age_limit":"Confirm on current ticketing.","source_urls":["https://ra.co/events/2537924"],"research_status":"ticketing_listing_and_safer_space_policy_verified","updated_at":"2026-09-26T00:00:00Z"}}
]
$qa_gnb_city_events$) e(name text,aliases jsonb,city text,date date,start_date date,end_date date,description text,link text,ticket_url text,location text,lat double precision,lng double precision,vibe text,intel jsonb)
), matched as (
 select s.*,x.id existing_id from src s left join lateral (select e.id from public.events e where lower(trim(e.city))=lower(trim(s.city)) and (lower(regexp_replace(trim(e.name),'[^a-z0-9]+','','gi'))=lower(regexp_replace(trim(s.name),'[^a-z0-9]+','','gi')) or exists(select 1 from jsonb_array_elements_text(s.aliases) a where lower(regexp_replace(trim(e.name),'[^a-z0-9]+','','gi'))=lower(regexp_replace(trim(a),'[^a-z0-9]+','','gi'))) or (e.start_date=s.start_date and lower(nullif(trim(e.link),'')) in(lower(s.link),lower(s.ticket_url)))) limit 1)x on true
), updated as (
 update public.events e set name=s.name,description=s.description,link=s.link,ticket_url=s.ticket_url,date=s.date,start_date=s.start_date,end_date=s.end_date,location=s.location,lat=s.lat,lng=s.lng,vibe=s.vibe,vibe_tags=array[]::text[],event_intel=s.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from matched s where e.id=s.existing_id returning e.id
)
insert into public.events(name,city,description,link,ticket_url,date,start_date,end_date,location,lat,lng,vibe,vibe_tags,event_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,description,link,ticket_url,date,start_date,end_date,location,lat,lng,vibe,array[]::text[],intel,true,'approved',timezone('utc',now()) from matched where existing_id is null;

with src as (
 select * from jsonb_to_recordset($qa_gnb_global_events$
[{"name":"PIP presents PARISH","aliases":["PARISH The Hague 2026"],"date":"2026-10-17","start_date":"2026-10-17","end_date":"2026-10-18","description":"PARISH turns PIP into an all-sensory queer club encounter: ghetto tech and techno beside sound healing, yoga, community DJ slots and an awareness team that makes the party's care visible.","link":"https://ra.co/events/2506097","ticket_url":"https://ra.co/events/2506097","location":"PIP Den Haag, Binckhorstlaan 36, 2513 The Hague, Netherlands","vibe":"queer techno and ghetto-tech gathering with community slots, movement and care","intel":{"hours":"23:59 Saturday 17 October–06:00 Sunday 18 October 2026.","entry_wait":"€10–18 RA tickets and an 18+ door are listed; advance purchase is sensible for the focused club capacity.","best_arrival":"Reach the venue close to 23:59 to enter before the peak and connect with the wider programme beyond the DJ bill.","crowd_mix":"Queer dancers, techno and ghetto-tech heads, community contributors and guests who understand a safer-space floor are the intended mix.","dress_code":"No fixed dress code is published; expressive, comfortable clubwear suits a night that combines movement, sound healing and hard club music.","host_inclusivity":"PARISH explicitly identifies as queer, bans racism, homophobia, sexism, transphobia and ableism, and has an awareness team on site.","lineup":"ARTÉMIS, BBKAY live with SOHOTSOSPICY, Cette Crevette, Démonia Gráfica, Kahi Baby, PR1N6666R1R1, VENDORS SYDS, Wolf Cutt and community DJs; yoga by aer.yoga.","age_limit":"18+.","source_urls":["https://ra.co/events/2506097"],"research_status":"ticketing_listing_and_awareness_policy_verified_off_grid_city","updated_at":"2026-09-26T00:00:00Z"}}]
$qa_gnb_global_events$) e(name text,aliases jsonb,date date,start_date date,end_date date,description text,link text,ticket_url text,location text,vibe text,intel jsonb)
), matched as (
 select s.*,x.id existing_id from src s left join lateral (select g.id from public.global_events g where lower(regexp_replace(trim(g.name),'[^a-z0-9]+','','gi'))=lower(regexp_replace(trim(s.name),'[^a-z0-9]+','','gi')) or exists(select 1 from jsonb_array_elements_text(s.aliases) a where lower(regexp_replace(trim(g.name),'[^a-z0-9]+','','gi'))=lower(regexp_replace(trim(a),'[^a-z0-9]+','','gi'))) or (g.start_date=s.start_date and lower(nullif(trim(g.link),'')) in(lower(s.link),lower(s.ticket_url))) limit 1)x on true
), updated as (
 update public.global_events g set name=s.name,description=s.description,link=s.link,ticket_url=s.ticket_url,date=s.date,start_date=s.start_date,end_date=s.end_date,location=s.location,vibe=s.vibe,vibe_tags=array[]::text[],event_intel=s.intel,source='Queer Atlas editorial verification',last_checked='2026-09-26',event_status='scheduled' from matched s where g.id=s.existing_id returning g.id
)
insert into public.global_events(name,date,start_date,end_date,location,vibe,vibe_tags,description,link,ticket_url,event_intel,source,last_checked,event_status)
select name,date,start_date,end_date,location,vibe,array[]::text[],description,link,ticket_url,intel,'Queer Atlas editorial verification','2026-09-26','scheduled' from matched where existing_id is null;

do $qa_gnb_batch4_guard$
begin
 if exists(select 1 from public.events where event_intel->>'updated_at'='2026-09-26T00:00:00Z' and (coalesce(trim(description),'')='' or coalesce(trim(location),'')='' or jsonb_array_length(coalesce(event_intel->'source_urls','[]'::jsonb))=0)) then raise exception 'Germany Netherlands Belgium city event missing editorial data'; end if;
 if exists(select 1 from public.global_events where event_intel->>'updated_at'='2026-09-26T00:00:00Z' and (coalesce(trim(description),'')='' or coalesce(trim(location),'')='' or jsonb_array_length(coalesce(event_intel->'source_urls','[]'::jsonb))=0)) then raise exception 'Germany Netherlands Belgium global event missing editorial data'; end if;
end;
$qa_gnb_batch4_guard$;

commit;
